// spec: .qa/e2e/specs/promo-filter.md
// seed: tests/seed.hunter_free.spec.ts
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.join(__dirname, '../../../auth/hunter_free.json') });

const SECTION = 'Promotion & distribution';
const VALUES = ['All', 'No promotion', 'Promotion', 'Distribution', 'Unique Position'];

test.describe('Promotion filter — jobs and tenders lists (#521d84)', () => {
  test('English: the filter and its values are translated @desktop @prod-safe #521d84', async ({ page }) => {
    const sidebar = page.getByRole('complementary');
    const section = sidebar.getByRole('button', { name: SECTION, exact: true });
    const option = (name: string) => sidebar.getByRole('checkbox', { name, exact: true });
    const count = page.getByText(/^\d+ results?$/);

    // 1. Open /collaborations, switch the language to English in the header
    await page.goto('/collaborations');
    await page.getByRole('button', { name: 'שפה' }).click();
    await page.getByRole('button', { name: 'English', exact: true }).click();
    await expect(page).toHaveURL(/\/en\/collaborations/);
    await expect(count).toBeVisible();

    // 2. Open the promotion filter section
    await expect(section).toBeVisible();
    if ((await section.getAttribute('aria-expanded')) !== 'true') await section.click();
    await expect(section).toHaveAttribute('aria-expanded', 'true');

    // Expected: title and all values in English, no Hebrew, no raw keys; «All» selected (AC8)
    const list = section.locator('xpath=following-sibling::*[1]');
    const texts = [await section.innerText(), ...(await list.getByRole('listitem').allInnerTexts())].map((t) => t.trim());
    expect(texts.length).toBe(VALUES.length + 1);
    for (const t of texts) {
      expect(t, `Hebrew text in «${t}»`).not.toMatch(/[֐-׿]/);
      expect(t, `raw i18n key in «${t}»`).not.toMatch(/^[\w-]+(\.[\w-]+)+$/);
    }
    for (const v of VALUES) await expect(option(v)).toBeVisible();
    await expect(option('All')).toBeChecked();
    for (const v of VALUES.slice(1)) await expect(option(v)).not.toBeChecked();

    // 3. Choose «Promotion» (counterpart of «קידום»)
    await option('Promotion').click();

    // Expected: count in English, removable chip (AC4, AC7)
    await expect(page).toHaveURL(/[?&]promo=[^&]+/);
    await expect(count).toBeVisible();
    const chip = page.getByRole('button', { name: 'Remove filter: Promotion', exact: true });
    await expect(chip).toBeVisible();
    await expect(chip).toContainText('×');
    await expect(chip).not.toContainText(/[֐-׿]/);
  });
});
